1	'use strict'
2	
3	// The one brain interface, two implementations. No classes needed.
4	// decide(state) -> { action: 'fight' | 'follow' | 'roam' | 'idle', sprint: bool, source }
5	// state = { distance_to_player, player_visible, player_moving, bot_health, bot_food, nearby_hostiles, hostile_distance, hostile_near_player }
6	
7	const JEV_ENDPOINT = 'https://api.typesafe.ai/v1/systemone'
8	const JEV_MODEL = 'jev-latest'
9	
10	// Remote-brain source name: the JEV hostname stays 'jev', anything else
11	// (e.g. the compose service laya) is addressed by its own hostname.
12	function sourceForUrl(url) {
13	  try {
14	    const host = new URL(url).hostname
15	    return host === 'api.typesafe.ai' ? 'jev' : host
16	  } catch {
17	    return 'jev'
18	  }
19	}
20	
21	const stubBrain = {
22	  name: 'stub',
23	  decide(state) {
24	    const hd = state.hostile_distance
25	    const near = !!state.hostile_near_player
26	    const health = typeof state.bot_health === 'number' ? state.bot_health : 20
27	    if (((typeof hd === 'number' && hd <= 8) || near) && health >= 6) {
28	      return { action: 'fight', sprint: false, source: 'stub' }
29	    }
30	    const d = state.distance_to_player
31	    if (typeof d !== 'number') return { action: 'idle', sprint: false, source: 'stub' }
32	    if (d > 3) return { action: 'follow', sprint: d > 8, source: 'stub' }
33	    // Roam ranks last: close to a standing player with no hostile near.
34	    // A moving player means idle (wait for them); any hostile fact means
35	    // idle too — fight (or caution at low health) owns the body instead.
36	    if (!state.player_moving && typeof hd !== 'number' && !near) {
37	      return { action: 'roam', sprint: false, source: 'stub' }
38	    }
39	    return { action: 'idle', sprint: false, source: 'stub' }
40	  }
41	}
42	
43	function parseAction(answer) {
44	  const choice = answer && answer.choice
45	  return choice === 'fight' || choice === 'follow' || choice === 'roam' || choice === 'idle' ? choice : null
46	}
47	
48	// Noul answers are documented as {"type":"noul","noul":0..1} (0..1
49	// probability, no confidence field).
50	function parseNoul(answer) {
51	  return typeof answer?.noul === 'number' ? answer.noul >= 0.5 : false
52	}
53	
54	// JEV `state` is documented as a string; send one compact text line.
55	function stateToText(state) {
56	  if (typeof state === 'string') return state
57	  const d = state.distance_to_player
58	  const hd = state.hostile_distance
59	  return `distance_to_player=${typeof d === 'number' ? d.toFixed(1) : 'none'} ` +
60	    `player_visible=${!!state.player_visible} ` +
61	    `player_moving=${!!state.player_moving} ` +
62	    `bot_health=${state.bot_health} bot_food=${state.bot_food} ` +
63	    `nearby_hostiles=${state.nearby_hostiles} ` +
64	    `hostile_distance=${typeof hd === 'number' ? hd.toFixed(1) : 'none'} ` +
65	    `hostile_near_player=${!!state.hostile_near_player}`
66	}
67	
68	function jevBrain(apiKey, fetchFn, timeoutMs = 1000, url = JEV_ENDPOINT) {
69	  const doFetch = fetchFn || fetch
70	  const source = sourceForUrl(url)
71	  return {
72	    name: source,
73	    async decide(state) {
74	      // ponytail: one call per tick, no batching/caching — upgrade path is
75	      // batching states if JEV cost ever matters ($0.042/M tokens; ~200
76	      // tokens/tick -> pennies/day).
77	      try {
78	        const headers = { 'Content-Type': 'application/json' }
79	        if (apiKey) headers.Authorization = `Bearer ${apiKey}`
80	        const res = await doFetch(url, {
81	          method: 'POST',
82	          signal: AbortSignal.timeout(timeoutMs),
83	          headers,
84	          body: JSON.stringify({
85	            model: JEV_MODEL,
86	            state: stateToText(state),
87	            questions: {
88	              action: {
89	                type: 'choice',
90	                instructions: 'Decide what the companion bot does this second. Fight when a hostile mob is within 8 blocks of the bot or near the player and the bot has at least 6 health. Otherwise follow when the player is more than 3 blocks away. Otherwise roam when the player is within 3 blocks and is not moving and no hostile mob is near. Otherwise wait.',
91	                criteria: {
92	                  fight: 'A hostile mob is within 8 blocks (or near the player) and bot_health is 6 or more: attack the mob.',
93	                  follow: 'The player is far away (more than 3 blocks): the bot should walk toward the player and stay close.',
94	                  idle: 'The player is already within 3 blocks: the bot should stand still and wait.',
95	                  roam: 'The player is within 3 blocks and is not moving, and no hostile mob is near: walk a few blocks around the player to look at the surroundings.'
96	                }
97	              },
98	              sprint: {
99	                type: 'noul',
100	                instructions: 'The player is more than 8 blocks away and moving, so the bot should sprint to catch up.',
101	                criteria: {
102	                  true: 'sprint to catch up',
103	                  false: 'walking is enough'
104	                }
105	              }
106	            }
107	          })
108	        })
109	        if (!res.ok) throw new Error(`jev http ${res.status}`)
110	        const data = await res.json()
111	        let action = parseAction(data && data.answers && data.answers.action)
112	        if (!action) throw new Error('jev missing action answer')
113	        const sprint = parseNoul(data.answers.sprint)
114	        const ref = stubBrain.decide(state).action
115	        if (ref !== action) {
116	          console.error(`brain disagree source=${source} model=${action} stub=${ref} state=${stateToText(state)}`)
117	        }
118	        return { action, sprint, source }
119	      } catch (err) {
120	        // 429/529 back off by falling through to the stub; the next tick
121	        // retries naturally. Never crash the bot because of the brain.
122	        console.error(`brain jev error, stub fallback: ${err && err.message ? err.message : err}`)
123	        const fallback = stubBrain.decide(state)
124	        fallback.source = 'stub-fallback'
125	        return fallback
126	      }
127	    }
128	  }
129	}
130	
131	function makeBrain(env) {
132	  const customUrl = env && env.BRAIN_URL
133	  const key = env && env.TYPESAFE_API_KEY
134	  if (customUrl || key) {
135	    const url = customUrl || JEV_ENDPOINT
136	    const source = sourceForUrl(url)
137	    console.log(`brain=${source}`)
138	    const rawTimeout = (env && env.BRAIN_TIMEOUT_MS) || (env && env.BRAIN_TICK_MS) || '1000'
139	    const timeoutMs = parseInt(rawTimeout, 10)
140	    return jevBrain(key, undefined, Number.isFinite(timeoutMs) ? timeoutMs : 1000, url)
141	  }
142	  console.log('brain=stub')
143	  return stubBrain
144	}
145	
